def corrected(q, tpr, tnr):
    return min(1.0, max(0.0, (q + tnr - 1) / (tpr + tnr - 1)))

print(round(corrected(0.55, 0.80, 0.85), 2))

def kappa(human, judge):
    n = len(human)
    p_o = sum(h == j for h, j in zip(human, judge)) / n
    p_e = sum((human.count(k) / n) ** 2 for k in set(human))
    return (p_o - p_e) / (1 - p_e)
